'use strict';

// Loupe & Lettres — créé avec l'aide de l'IA
// Invoice totals with integer arithmetic (BigInt): one explicit rounding rule, a stated-total check and a printable HTML page.
// Pure function of its input: it keeps no state, so it cannot guarantee that an invoice number is unused.
const CURRENCIES = new Set(['EUR', 'USD', 'GBP', 'CHF']);
const MAX_LINES = 200;
const MAX_CENTS = 10n ** 13n;

function scaled(value, maxDecimals, label) {
  const text = typeof value === 'number' ? String(value) : value;
  if (typeof text !== 'string' || !new RegExp(`^\\d+(?:\\.\\d{1,${maxDecimals}})?$`).test(text.trim())) {
    throw new Error(`${label} must be a non-negative decimal with at most ${maxDecimals} decimals`);
  }
  const [whole, fraction = ''] = text.trim().split('.');
  return BigInt(whole + fraction.padEnd(maxDecimals, '0'));
}
const halfUp = (numerator, denominator) => (numerator + denominator / 2n) / denominator;
const money = cents => `${cents / 100n}.${String(cents % 100n).padStart(2, '0')}`;
const plain = (scaledValue, decimals) => {
  const digits = String(scaledValue).padStart(decimals + 1, '0');
  const whole = digits.slice(0, digits.length - decimals), fraction = digits.slice(digits.length - decimals).replace(/0+$/, '');
  return fraction ? `${whole}.${fraction}` : whole;
};
const toNumber = (cents, label) => {
  if (cents > MAX_CENTS) throw new Error(`${label} is too large`);
  return Number(cents);
};
const escapeHtml = text => String(text).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;').replace(/'/g, '&#39;');

function validDate(text) {
  const match = /^(\d{4})-(\d{2})-(\d{2})$/.exec(typeof text === 'string' ? text : '');
  if (!match) return false;
  const [year, month, day] = match.slice(1).map(Number);
  const leap = year % 4 === 0 && (year % 100 !== 0 || year % 400 === 0);
  const days = [31, leap ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
  return year >= 1900 && year <= 2199 && month >= 1 && month <= 12 && day >= 1 && day <= days[month - 1];
}

// Suggests the number after `last` by incrementing its trailing digits and keeping the zero padding.
function nextInvoiceNumber(last) {
  const match = /^(.*?)(\d+)$/s.exec(typeof last === 'string' ? last.trim() : '');
  if (!match) throw new Error('Invoice number must end with digits to be incremented');
  const next = String(BigInt(match[2]) + 1n).padStart(match[2].length, '0');
  return match[1] + next;
}

function computeInvoice(input) {
  if (!input || typeof input !== 'object') throw new Error('Input must be an object');
  const invoiceNumber = typeof input.invoiceNumber === 'string' ? input.invoiceNumber.trim() : '';
  if (!invoiceNumber || invoiceNumber.length > 40) throw new Error('invoiceNumber must be 1 to 40 characters');
  if (!validDate(input.issueDate)) throw new Error('issueDate must be a valid calendar date YYYY-MM-DD');
  const currency = typeof input.currency === 'string' ? input.currency.trim().toUpperCase() : '';
  if (!CURRENCIES.has(currency)) throw new Error('currency must be EUR, USD, GBP or CHF');
  const vatRounding = input.vatRounding === undefined ? 'per_group' : input.vatRounding;
  if (vatRounding !== 'per_group' && vatRounding !== 'per_line') throw new Error('vatRounding must be per_group or per_line');
  for (const name of ['seller', 'buyer']) {
    if (input[name] !== undefined && (typeof input[name] !== 'string' || input[name].length > 300)) throw new Error(`${name} must be text of at most 300 characters`);
  }
  if (!Array.isArray(input.lines) || input.lines.length < 1 || input.lines.length > MAX_LINES) throw new Error(`lines must be a list of 1 to ${MAX_LINES} items`);

  const groups = new Map();
  const lines = input.lines.map((line, i) => {
    const n = i + 1;
    try {
      if (!line || typeof line !== 'object') throw new Error('line must be an object');
      const description = typeof line.description === 'string' ? line.description.trim() : '';
      if (!description || description.length > 200) throw new Error('description must be 1 to 200 characters');
      const quantity = scaled(line.quantity, 3, 'quantity');
      if (quantity === 0n) throw new Error('quantity must be greater than zero');
      const unitPrice = scaled(line.unitPrice, 4, 'unitPrice');
      const rate = scaled(line.vatRate, 2, 'vatRate');
      if (rate > 10000n) throw new Error('vatRate must be between 0 and 100');
      const net = halfUp(quantity * unitPrice, 100000n);
      const lineVat = halfUp(net * rate, 10000n);
      const group = groups.get(rate) || { net: 0n, lineVat: 0n };
      groups.set(rate, { net: group.net + net, lineVat: group.lineVat + lineVat });
      return { line: n, description, quantity: plain(quantity, 3), unitPrice: plain(unitPrice, 4), vatRate: plain(rate, 2), netCents: toNumber(net, 'line amount'), vatCents: vatRounding === 'per_line' ? toNumber(lineVat, 'line VAT') : null };
    } catch (error) { throw new Error(`Line ${n}: ${error.message}`); }
  });

  const vatGroups = [...groups].sort((a, b) => (a[0] < b[0] ? -1 : 1)).map(([rate, g]) => {
    const vat = vatRounding === 'per_line' ? g.lineVat : halfUp(g.net * rate, 10000n);
    return { vatRate: plain(rate, 2), netCents: toNumber(g.net, 'group amount'), vatCents: toNumber(vat, 'group VAT') };
  });
  const net = vatGroups.reduce((sum, g) => sum + BigInt(g.netCents), 0n);
  const vat = vatGroups.reduce((sum, g) => sum + BigInt(g.vatCents), 0n);
  const totals = { netCents: toNumber(net, 'total'), vatCents: toNumber(vat, 'total VAT'), grossCents: toNumber(net + vat, 'total') };

  let check = null;
  if (input.declaredTotal !== undefined && input.declaredTotal !== null && input.declaredTotal !== '') {
    const declared = scaled(input.declaredTotal, 2, 'declaredTotal');
    check = { declaredCents: toNumber(declared, 'declaredTotal'), computedCents: totals.grossCents, matches: declared === net + vat, differenceCents: Number(declared - net - vat) };
  }

  let suggestedNextNumber = null;
  try { suggestedNextNumber = nextInvoiceNumber(invoiceNumber); } catch (error) { suggestedNextNumber = null; }

  const cell = text => `<td>${escapeHtml(text)}</td>`;
  const num = text => `<td class="n">${escapeHtml(text)}</td>`;
  const html = [
    '<!doctype html><html lang="en"><head><meta charset="utf-8"><title>' + escapeHtml(`Invoice ${invoiceNumber}`) + '</title>',
    '<style>body{font-family:Arial,sans-serif;margin:2rem;color:#111}table{border-collapse:collapse;width:100%;margin:1rem 0}th,td{border-bottom:1px solid #ccc;padding:.35rem;text-align:left}.n{text-align:right}tfoot td{font-weight:bold}small{color:#555}@media print{body{margin:0}}</style></head><body>',
    `<h1>Invoice ${escapeHtml(invoiceNumber)}</h1><p>Date: ${escapeHtml(input.issueDate)} &middot; Currency: ${currency}</p>`,
    input.seller ? `<p><strong>From</strong><br>${escapeHtml(input.seller).replace(/\n/g, '<br>')}</p>` : '',
    input.buyer ? `<p><strong>To</strong><br>${escapeHtml(input.buyer).replace(/\n/g, '<br>')}</p>` : '',
    '<table><thead><tr><th>Description</th><th class="n">Qty</th><th class="n">Unit price</th><th class="n">VAT %</th><th class="n">Net</th></tr></thead><tbody>',
    ...lines.map(l => `<tr>${cell(l.description)}${num(l.quantity)}${num(l.unitPrice)}${num(l.vatRate)}${num(money(BigInt(l.netCents)))}</tr>`),
    '</tbody><tfoot>',
    ...vatGroups.map(g => `<tr><td colspan="4">VAT ${escapeHtml(g.vatRate)}% on ${escapeHtml(money(BigInt(g.netCents)))}</td>${num(money(BigInt(g.vatCents)))}</tr>`),
    `<tr><td colspan="4">Total net</td>${num(money(net))}</tr><tr><td colspan="4">Total VAT</td>${num(money(vat))}</tr><tr><td colspan="4">Total to pay (${currency})</td>${num(money(net + vat))}</tr>`,
    '</tfoot></table>',
    '<small>Computed with a free Loupe &amp; Lettres workflow (créé avec l\'aide de l\'IA). Legal invoice mentions depend on your country and status; check them yourself.</small></body></html>',
  ].join('\n');

  return {
    invoiceNumber, issueDate: input.issueDate, currency, vatRounding,
    lines, vatGroups, totals, check, suggestedNextNumber,
    totalsText: { net: money(net), vat: money(vat), gross: money(net + vat) },
    html,
    limitations: 'Integer arithmetic, half-up rounding of each amount to the cent. Only one VAT rounding rule per invoice (per_group or per_line). The workflow stores no counter: it only suggests the next number, and you must check that it is unused. It is not a legal invoice validator, a tax calculation for your country or accounting advice.',
  };
}


return [{ json: computeInvoice($input.first().json) }];
